INSERT INTO LIVROS_NOMES (NOME, ESTADO, MOTIVO, CONFERIDO, SUBTIPO, CRIADO_EM) SELECT MIN(L.TITULO), '{{estado}}', NULLIF(LEFT('{{motivo}}', 300), ''), 'IMPORTADO', NULLIF('{{subtipo}}', ''), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS L WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci LIKE '{{padrao}}' GROUP BY L.TITULO COLLATE utf8mb4_0900_ai_ci LIMIT 1 ON DUPLICATE KEY UPDATE ESTADO = '{{estado}}', CATALOGO_ID = NULL, SUBTIPO = VALUES(SUBTIPO), MOTIVO = COALESCE(VALUES(MOTIVO), MOTIVO), CONFERIDO = IF(CONFERIDO = 'ACEITO', 'ACEITO', 'IMPORTADO')